def recolor(fragment, src, dst, src_palette=None):
    """Shift the shades of tincture `src` to tincture `dst` (in the active palette).

    src_palette is the palette the fragment was drawn in: Sodacan's by default, a house's
    for that house's own charges.
    """
    target = _active["palette"]
    src_palette = src_palette or PALETTE
    if (src == dst and target is src_palette) or src not in src_palette or dst not in target:
        return fragment
    sh, sl, ss = _hls(src_palette[src])
    dh, dl, ds = _hls(target[dst])
    src_neutral = ss < 0.15

    def sub(m):
        col = m.group(0).lower()
        if len(col) == 4:
            col = "#" + "".join(ch * 2 for ch in col[1:])
        h, l, s = _hls(col)
        if src_neutral:
            if s > 0.15 or abs(l - sl) > 0.35:
                return m.group(0)
        elif s < 0.2 or min(abs(h - sh), 1 - abs(h - sh)) > 0.07:
            return m.group(0)
        return _hex(dh, l + (dl - sl), ds if src_neutral else s * (ds / ss if ss else 1))

    return re.sub(r"#[0-9a-fA-F]{6}\b|#[0-9a-fA-F]{3}\b", sub, fragment)


ROUNDELS = {"roundel", "bezant", "plate", "torteau", "hurt", "pellet", "ogress", "pomme", "golpe",
            "guze", "orange"}
MULLET_RATIO = 0.382  # inner/outer radius: his mullets are true pentagrams (measured 0.37)


def _geometric(c, slots):
    """One path (page units) drawing a geometric charge in every slot, the way his files
    draw mullets: a flat fill, no outline, all of a group in one path. None if c is not
    one of these shapes."""
    import math
    kind = c.kind
    attrs = " ".join(c.attributes)
    if kind in ("latin cross", "passion cross", "cross") and not c.ordinary:
        # a cross as a mobile charge: an upright and a crossbar, the Latin cross with its
        # crossbar a third of the way down (proportions conventional)
        subs = []
        for x0, y0, x1, y1 in slots:
