import re
rows=[]
for l in open('scratch/tarot/batch_cmp.txt',encoding='utf8'):
    m=re.match(r'(.+?\.svg)\s+([\d.]+) ->\s+([\d.]+) MB  PSNR ([\d.]+)  >24: ([\d.]+)%  >48: ([\d.]+)%',l)
    rows.append((m.group(1),float(m.group(2)),float(m.group(3)),float(m.group(4)),float(m.group(5)),float(m.group(6))))
print(len(rows),'cards; total %.1f -> %.1f MB (%.0f%% smaller)'%(sum(r[1] for r in rows),sum(r[2] for r in rows),100*(1-sum(r[2] for r in rows)/sum(r[1] for r in rows))))
for r in sorted(rows,key=lambda r:r[3])[:5]: print('lowest PSNR',r)
for r in sorted(rows,key=lambda r:-r[5])[:3]: print('most >48',r)
"

